"""Vectorised evaluation of grounded AST formulas over integer cell columns.

This is the exact-arithmetic sibling of :mod:`netnomos.theory`: the same AST
produced by :mod:`netnomos.ast` / :mod:`netnomos.projection` is evaluated on
NumPy ``int64`` columns instead of pandas rows.  All protocol values fit in
int64 (cells and constants are <= 1_000_000, a scale is <= 65535 and a sum has
at most K <= 4 terms), so comparisons are exact and never wrap or saturate.
"""
from __future__ import annotations

import numpy as np

from netnomos.ast import (
    BinaryTerm,
    BoolAnd,
    BoolConst,
    BoolNot,
    BoolOr,
    Compare,
    Constant,
    FuncCall,
    Implies,
    SymbolRef,
)

COMPARATORS = {
    '=': np.equal,
    '!=': np.not_equal,
    '<': np.less,
    '<=': np.less_equal,
    '>': np.greater,
    '>=': np.greater_equal,
}


def scalar(value) -> np.int64:
    return np.int64(value)


def term_to_array(term, columns: dict[str, np.ndarray], count: int):
    """Value of ``term`` as an int64 array of length ``count`` (or a scalar)."""
    if isinstance(term, Constant):
        return scalar(term.value)
    if isinstance(term, SymbolRef):
        return columns[term.name]
    if isinstance(term, BinaryTerm):
        left = term_to_array(term.left, columns, count)
        right = term_to_array(term.right, columns, count)
        if term.op == '+':
            return np.add(left, right, dtype=np.int64)
        if term.op == '-':
            return np.subtract(left, right, dtype=np.int64)
        if term.op == '*':
            return np.multiply(left, right, dtype=np.int64)
        raise ValueError(f'unsupported arithmetic op: {term.op!r}')
    if isinstance(term, FuncCall):
        args = [term_to_array(arg, columns, count) for arg in term.args]
        name = term.name.lower()
        if name == 'sum':
            result = np.zeros(count, dtype=np.int64)
            for arg in args:
                result += arg
            return result
        if name in ('min', 'max'):
            reduce = np.minimum.reduce if name == 'min' else np.maximum.reduce
            return reduce(np.stack(args), axis=0)
        raise ValueError(f'unsupported aggregation: {term.name!r}')
    raise TypeError(f'unsupported term node: {type(term)!r}')


def formula_to_array(formula, columns: dict[str, np.ndarray], count: int) -> np.ndarray:
    """Boolean column of length ``count`` holding the formula's truth values."""
    if isinstance(formula, BoolConst):
        return np.full(count, bool(formula.value), dtype=bool)
    if isinstance(formula, Compare):
        left = term_to_array(formula.left, columns, count)
        right = term_to_array(formula.right, columns, count)
        result = COMPARATORS[formula.op](left, right)
        result = np.asarray(result, dtype=bool)
        if result.ndim == 0:
            result = np.full(count, bool(result), dtype=bool)
        return result
    if isinstance(formula, BoolNot):
        return ~formula_to_array(formula.value, columns, count)
    if isinstance(formula, BoolAnd):
        result = np.ones(count, dtype=bool)
        for value in formula.values:
            result &= formula_to_array(value, columns, count)
        return result
    if isinstance(formula, BoolOr):
        result = np.zeros(count, dtype=bool)
        for value in formula.values:
            result |= formula_to_array(value, columns, count)
        return result
    if isinstance(formula, Implies):
        return (~formula_to_array(formula.left, columns, count)) | formula_to_array(
            formula.right, columns, count
        )
    raise TypeError(f'unsupported formula node: {type(formula)!r}')


def truth_columns(formulas, columns: dict[str, np.ndarray], count: int) -> list[np.ndarray]:
    return [formula_to_array(formula, columns, count) for formula in formulas]


def bitset(mask: np.ndarray) -> int:
    """Pack a boolean column into an integer bitset (bit ``i`` ⇔ ``mask[i]``)."""
    packed = np.packbits(np.asarray(mask, dtype=bool), bitorder='little')
    return int.from_bytes(packed.tobytes(), 'little')
